/**
 * A command list behind a trigger (`design/components/menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/menu'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  afresh,
  agentMember,
  anchorProps,
  chooseMenuEntry,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  followHighlight,
  menuChoices,
  mergeParts,
  ownerContext,
  provide,
  scope,
  syncTriggerAnchor,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Kbd from '../structure/Kbd'
import MenuSubmenu from './MenuSubmenu'

export type MenuPresentation = NonNullable<MenuProps['presentation']>

export type MenuAlign = NonNullable<MenuProps['align']>

export interface MenuItemEntry {
  kind?: 'item'
  label: string
  icon?: IconRole
  kbd?: string
  tone?: 'neutral' | 'danger'
  disabled?: boolean
  onSelect: () => void
}

export interface MenuCheckboxEntry {
  kind: 'checkbox'
  label: string
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  disabled?: boolean
}

export interface MenuSeparatorEntry {
  kind: 'separator'
}

export interface MenuLabelEntry {
  kind: 'label'
  label: string
}

export type MenuLeafEntry = MenuItemEntry | MenuCheckboxEntry | MenuSeparatorEntry | MenuLabelEntry

export interface MenuSubmenuEntry {
  kind: 'submenu'
  label: string
  icon?: IconRole
  disabled?: boolean
  items: MenuLeafEntry[]
}

export type MenuEntry = MenuLeafEntry | MenuSubmenuEntry

export interface MenuProps {
  align?: 'start' | 'end'
  /**
   * Opens on mount, for galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  items: MenuEntry[]
  onOpenChange?: (open: boolean) => void
  /**
   * The controlled pair; uncontrolled is the default. Use it to keep the menu open across
   * several checkbox toggles, or to close it on "apply".
   */
  open?: boolean
  /**
   * `'auto'` uses a sheet below `30rem` (the sheet presentation, `design/components/README.md`),
   * the phone's standard pattern for "choose from these". `'popover'` keeps the popper at every
   * width, for the rare pointer-first embed that needs precision. There is no always-`'sheet'`
   * value, because a bottom sheet does not suit a wide pointer surface, and the closed union
   * rejects it (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  /**
   * A governed control, usually a `Button` with `iconOnly icon="overflow"`.
   */
  trigger: JSX.Element
}

/** What Menu hands its compound parts. */
export interface MenuOwner {
  readonly api: zag.Api
  readonly service: zag.Service
}

/** A command list behind a trigger. */
export default function Menu(given: MenuProps): JSX.Element {
  const props = mergeProps(
    { align: 'start', presentation: 'auto' } as Defaults<MenuProps, 'align' | 'presentation'>,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<MenuOwner>('Menu'), {
      get api() {
        return api.value
      },
      get service() {
        return service
      },
    })
    const uid = createUniqueId()
    const anchor = elementRef<HTMLElement>()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const flat = createDerived(() =>
      props.items.flatMap((entry) =>
        entry.kind === 'submenu'
          ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
          : [entry],
      ),
    )
    const documentDirection = useDirection(() => anchor.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          positioning: { placement: `bottom-${props.align}`, gutter: 2 },
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
          onSelect: (details) => {
            flat.value.forEach(
              (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    const effect2 = () => {
      followHighlight(panel.value, api.value.highlightedValue)
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect2,
      true,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'Menu',
        element: () => anchor.value?.querySelector('button, a[href], [tabindex]'),
        state: () => ({ open: api.value.open, entries: menuChoices(props.items) }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              chooseMenuEntry(props.items, value) && api.value.open && api.value.setOpen(false),
          },
          open: () => api.value.open || api.value.setOpen(true),
          close: () => api.value.open && api.value.setOpen(false),
        },
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {/* trigger */}
        <span
          {...mergeParts(anchorProps(api.value.getTriggerProps()), { class: triggerAnchor.anchor })}
          ref={anchor.attach}
        >
          {props.trigger}
        </span>
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.content,
                      style: {
                        '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
                        '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
                      },
                      hidden: undefined,
                      'data-member': 'menu',
                      onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                    })}
                    ref={panel.attach}
                  >
                    <Each of={props.items} by={(_entry, index) => index} renew>
                      {(entry) => (
                        <>
                          {entry.kind === 'separator' ? (
                            <div
                              {...mergeParts(api.value.getSeparatorProps(), {
                                class: styles.separator,
                              })}
                            />
                          ) : entry.kind === 'label' ? (
                            <div class={styles.groupLabel}>{entry.label}</div>
                          ) : entry.kind === 'checkbox' ? (
                            <div
                              {...mergeParts(
                                api.value.getOptionItemProps({
                                  type: 'checkbox',
                                  value: entry.label,
                                  checked: entry.checked,
                                  disabled: entry.disabled,
                                  closeOnSelect: false,
                                  onCheckedChange: entry.onCheckedChange,
                                }),
                                {
                                  class: classes(styles.item, styles.checkbox),
                                  'data-menu-part': 'checkbox',
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              <span class={styles.check}>
                                {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                              </span>
                              <span class={styles.label}>{entry.label}</span>
                            </div>
                          ) : entry.kind === 'submenu' ? (
                            <MenuSubmenu entry={entry} />
                          ) : (
                            <div
                              {...mergeParts(
                                api.value.getItemProps({
                                  value: entry.label,
                                  disabled: entry.disabled,
                                }),
                                {
                                  class: styles.item,
                                  'data-tone': entry.tone ?? 'neutral',
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              {entry.icon !== undefined ? (
                                <span class={styles.glyph}>
                                  <Icon name={entry.icon} size="sm" />
                                </span>
                              ) : null}
                              <span class={styles.label}>{entry.label}</span>
                              {entry.kbd !== undefined ? (
                                <span class={styles.hint}>
                                  <Kbd>{entry.kbd}</Kbd>
                                </span>
                              ) : null}
                            </div>
                          )}
                        </>
                      )}
                    </Each>
                  </div>
                </div>
              ) : null}
              {scrimPresent() ? (
                <div
                  class={sheet.scrim}
                  data-state={api.value.open ? 'open' : 'closed'}
                  ref={scrim.attach}
                />
              ) : null}
              {sheetPresent() ? (
                <div class={sheet.positioner}>
                  <div
                    class={sheet.panel}
                    data-presentation="sheet"
                    data-state={api.value.open ? 'open' : 'closed'}
                    tabindex="-1"
                    ref={sheetPanel.attach}
                  >
                    {/* panel */}
                    <div
                      {...mergeParts(api.value.getContentProps(), {
                        class: styles.sheetList,
                        hidden: undefined,
                        'data-member': 'menu',
                        onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                      })}
                      ref={panel.attach}
                    >
                      <Each of={flat.value} by={(_entry, index) => index} renew>
                        {(entry) => (
                          <>
                            {entry.kind === 'separator' ? (
                              <div
                                {...mergeParts(api.value.getSeparatorProps(), {
                                  class: styles.separator,
                                })}
                              />
                            ) : entry.kind === 'label' ? (
                              <div class={styles.groupLabel}>{entry.label}</div>
                            ) : entry.kind === 'checkbox' ? (
                              <div
                                {...mergeParts(
                                  api.value.getOptionItemProps({
                                    type: 'checkbox',
                                    value: entry.label,
                                    checked: entry.checked,
                                    disabled: entry.disabled,
                                    closeOnSelect: false,
                                    onCheckedChange: entry.onCheckedChange,
                                  }),
                                  {
                                    class: classes(styles.item, styles.checkbox),
                                    'data-menu-part': 'checkbox',
                                    tabindex: '-1',
                                    onfocus: () => api.value.setHighlightedValue(entry.label),
                                  },
                                )}
                              >
                                <span class={styles.check}>
                                  {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                                </span>
                                <span class={styles.label}>{entry.label}</span>
                              </div>
                            ) : (
                              <div
                                {...mergeParts(
                                  api.value.getItemProps({
                                    value: entry.label,
                                    disabled: entry.disabled,
                                  }),
                                  {
                                    class: styles.item,
                                    'data-tone': entry.tone ?? 'neutral',
                                    tabindex: '-1',
                                    onfocus: () => api.value.setHighlightedValue(entry.label),
                                  },
                                )}
                              >
                                {entry.icon !== undefined ? (
                                  <span class={styles.glyph}>
                                    <Icon name={entry.icon} size="sm" />
                                  </span>
                                ) : null}
                                <span class={styles.label}>{entry.label}</span>
                                {entry.kbd !== undefined ? (
                                  <span class={styles.hint}>
                                    <Kbd>{entry.kbd}</Kbd>
                                  </span>
                                ) : null}
                              </div>
                            )}
                          </>
                        )}
                      </Each>
                    </div>
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
